399	        check(r.error.find(bad.string()) != std::string::npos,
400	              "unopenable leaf: error names the failed file");
401	        check(r.error.find("ermission") != std::string::npos ||
402	                  r.error.find("denied") != std::string::npos ||
403	                  r.error.find("cces") != std::string::npos,
404	              "unopenable leaf: error states open/permission reason");
405	        check(captured.first.empty() && captured.second.empty(),
406	              "unopenable leaf: library prints nothing, does not exit");
407	    }
408	
409	    // ---- 打开失败：有序批次中出错前已经处理过正常文件 ------------------
410	    {
411	        fault_test::FaultTrigger trigger(
412	            "BRANCHAUDIT_TEST_OPEN_FAIL", bad.string());
413	        branchaudit::FileHashResult r;
414	        auto captured = silent_merkle({good1, good2, bad}, &r);
415	        check(!r.ok(),
416	              "open failure after processed good files: whole batch fails");
417	        check(r.error.find(bad.string()) != std::string::npos,
418	              "open failure in batch: error points at the real failing file");
419	        check(r.error.find(good1.string()) == std::string::npos &&
420	                  r.error.find(good2.string()) == std::string::npos,
421	              "open failure in batch: already-processed files are not blamed");
422	        check(captured.first.empty(),
423	              "open failure in batch: no root of the processed prefix is printed");
424	        check(captured.second.empty(),
425	              "open failure in batch: library prints nothing");
426	        // 不得给出“仅前两个正常文件”的根。
427	        check(r.digest != branchaudit::merkle_parent(good_leaf1, good_leaf2),
428	              "open failure: root skipping the failing position is not returned");
429	        check(r.digest != good_leaf1,
430	              "open failure: a processed leaf is not returned as the root");
431	    }
432	
433	    // ---- 读取失败：叶子取得部分内容后继续读出错 ------------------------
434	    {
435	        fault_test::FaultTrigger trigger(
436	            "BRANCHAUDIT_TEST_READ_FAIL",
437	            bad.string() + ":" + std::to_string(kPartial));
438	        branchaudit::FileHashResult r;
439	        auto captured = silent_merkle({bad}, &r);
440	        check(!r.ok(), "read error mid-leaf: batch fails");
441	        check(r.error.find(bad.string()) != std::string::npos,
442	              "read failure: error names the failed file");
443	        check(r.error.find("read") != std::string::npos,
444	              "read failure: error says read failed rather than normal EOF");
445	        check(captured.first.empty() && captured.second.empty(),
446	              "read failure: library prints nothing");
447	        // 已读到的部分内容不能成为成功叶子摘要。
448	        check(r.digest != bad_partial_leaf,
449	              "read failure: partial leaf digest is not returned as success");
450	        check(r.digest != leaf_bytes(bad_bytes),
451	              "read failure: full-content leaf is not fabricated either");
452	    }
453	
454	    // ---- 读取失败：出错前正常文件已处理，仍整次失败且指向真正出错文件 --
455	    {
456	        fault_test::FaultTrigger trigger(
457	            "BRANCHAUDIT_TEST_READ_FAIL",
458	            bad.string() + ":" + std::to_string(kPartial));
459	        branchaudit::FileHashResult r;
460	        auto captured = silent_merkle({good1, bad, good2}, &r);
461	        check(!r.ok(),
462	              "read error after a good file: whole ordered batch fails");
463	        check(r.error.find(bad.string()) != std::string::npos,
464	              "batch read failure: error names the truly failing file");
465	        check(r.error.find(good1.string()) == std::string::npos &&
466	                  r.error.find(good2.string()) == std::string::npos,
467	              "batch read failure: good files are not named as the cause");
468	        check(captured.first.empty(),
469	              "batch read failure: no partial/skipped-position root is emitted");
470	        check(captured.second.empty(),
471	              "batch read failure: library prints nothing");
472	        check(r.digest != good_leaf1,
473	              "batch read failure: processed-prefix leaf is not a result");
474	    }
475	
476	    // ---- 空文件叶子在读取故障武装下仍正常读完 --------------------------
477	    {
478	        fault_test::FaultTrigger trigger(
479	            "BRANCHAUDIT_TEST_READ_FAIL",
480	            empty.string() + ":" + std::to_string(kPartial));
481	        branchaudit::FileHashResult r;
482	        auto captured = silent_merkle({empty}, &r);
483	        check(r.ok(),
484	              "empty file leaf reads to completion successfully (no content != error)");
485	        check(hex_of(r.digest) ==
486	                  "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
487	              "empty file leaf remains SHA-256(0x00)");
488	        check(captured.first.empty() && captured.second.empty(),
489	              "empty file leaf: library prints nothing");
490	    }
491	
492	    // ---- 故障只作用于指定路径：批次中其他文件不受影响 ------------------
493	    {
494	        fault_test::FaultTrigger trigger(
495	            "BRANCHAUDIT_TEST_READ_FAIL",
496	            bad.string() + ":" + std::to_string(kPartial));
497	        branchaudit::FileHashResult r;
498	        silent_merkle({good1, good2}, &r);
499	        check(r.ok() && r.digest == branchaudit::merkle_parent(good_leaf1, good_leaf2),
