517	void test_proofs() {
518	    TempArea tmp("proofs");
519	
520	    const auto empty = bytes_of("");
521	    const auto a = bytes_of("a");
522	    const auto abc = bytes_of("abc");
523	    const auto hello = bytes_of("hello\n");
524	
525	    const fs::path f_empty = tmp.root / "empty.bin";
526	    const fs::path f_a = tmp.root / "a.bin";
527	    const fs::path f_abc = tmp.root / "abc.bin";
528	    const fs::path f_hello = tmp.root / "hello.bin";
529	    write_file(f_empty, empty);
530	    write_file(f_a, a);
531	    write_file(f_abc, abc);
532	    write_file(f_hello, hello);
533	
534	    const Digest la = leaf_bytes(a);
535	    const Digest labc = leaf_bytes(abc);
536	    const Digest lempty = leaf_bytes(empty);
537	
538	    // 单文件批次：siblings 为空，root 等于 leaf。
539	    {
540	        const branchaudit::MerkleProofResult r =
541	            branchaudit::merkle_proof_file({f_a}, 0);
542	        check(r.ok(), "proof single file: succeeds");
543	        check(r.proof.leaf_count == 1 && r.proof.leaf_index == 0,
544	              "proof single file: count/index");
545	        check(r.proof.siblings.empty(), "proof single file: no siblings");
546	        check(r.proof.root == r.proof.leaf && r.proof.leaf == la,
547	              "proof single file: root equals leaf");
548	    }
549	    // 单个空文件同样如此。
550	    {
551	        const branchaudit::MerkleProofResult r =
552	            branchaudit::merkle_proof_file({f_empty}, 0);
553	        check(r.ok() && r.proof.siblings.empty() &&
554	                  r.proof.root == r.proof.leaf && r.proof.leaf == lempty,
555	              "proof single empty file: root equals leaf SHA-256(0x00)");
556	    }
557	
558	    // 两文件：兄弟侧向正确。
559	    {
560	        const branchaudit::MerkleProofResult r0 =
561	            branchaudit::merkle_proof_file({f_a, f_abc}, 0);
562	        check(r0.ok() && r0.proof.siblings.size() == 1,
563	              "proof [a, abc] index 0: one sibling");
564	        check(r0.proof.siblings[0].side == branchaudit::MerkleSibling::Side::right &&
565	                  r0.proof.siblings[0].digest == labc,
566	              "proof [a, abc] index 0: sibling on the right");
567	        check(r0.proof.root == branchaudit::merkle_parent(la, labc),
568	              "proof [a, abc] index 0: root matches pairing");
569	        const branchaudit::MerkleProofResult r1 =
570	            branchaudit::merkle_proof_file({f_a, f_abc}, 1);
571	        check(r1.ok() && r1.proof.siblings.size() == 1 &&
572	                  r1.proof.siblings[0].side == branchaudit::MerkleSibling::Side::left &&
573	                  r1.proof.siblings[0].digest == la,
574	              "proof [a, abc] index 1: sibling on the left");
575	        check(r1.proof.root == r0.proof.root,
576	              "proof root is identical for every position of the batch");
577	    }
578	
579	    // 三文件（奇数提升）：末位置的第一层没有兄弟记录。
580	    {
581	        const std::vector<fs::path> batch{f_a, f_abc, f_empty};
582	        const Digest p = branchaudit::merkle_parent(la, labc);
583	        const Digest expected_root = branchaudit::merkle_parent(p, lempty);
584	        check(root_of(batch) == expected_root, "proof fixture: 3-file root");
585	
586	        const branchaudit::MerkleProofResult r2 =
587	            branchaudit::merkle_proof_file(batch, 2);
588	        check(r2.ok() && r2.proof.leaf_count == 3 && r2.proof.leaf_index == 2,
589	              "proof [a, abc, empty] index 2: count/index");
590	        check(r2.proof.leaf == lempty, "proof index 2: leaf is SHA-256(0x00)");
591	        // 奇数末节点原样提升的层不添加记录：只有上层一个左侧兄弟。
592	        check(r2.proof.siblings.size() == 1 &&
593	                  r2.proof.siblings[0].side == branchaudit::MerkleSibling::Side::left &&
594	                  r2.proof.siblings[0].digest == p,
595	              "proof index 2: promoted level records no sibling");
596	        check(r2.proof.root == expected_root &&
597	                  fold_proof(r2.proof) == expected_root,
598	              "proof index 2: siblings fold back to the root");
599	
600	        const branchaudit::MerkleProofResult r0 =
601	            branchaudit::merkle_proof_file(batch, 0);
602	        check(r0.ok() && r0.proof.siblings.size() == 2 &&
603	                  r0.proof.siblings[0].side == branchaudit::MerkleSibling::Side::right &&
604	                  r0.proof.siblings[0].digest == labc &&
605	                  r0.proof.siblings[1].side == branchaudit::MerkleSibling::Side::right &&
606	                  r0.proof.siblings[1].digest == lempty,
607	              "proof index 0: siblings ordered from leaf to root");
608	        check(fold_proof(r0.proof) == r0.proof.root &&
609	                  r0.proof.root == expected_root,
610	              "proof index 0: folds to the same root");
611	    }
612	
613	    // 五文件（跨层奇数提升）：每个位置的证明都折回同一根，且根与
614	    // merkle_root_files 一致；中间被提升的层不记录兄弟。
615	    {
616	        const std::vector<fs::path> batch{f_a, f_abc, f_empty, f_hello, f_a};
617	        const Digest root = root_of(batch);
618	        check(hex_of(root) ==
619	                  "685686ca622026c4537dfdb49e8f9dac110c553f1d21aee96633e12fa47a7c47",
620	              "proof fixture: 5-file root matches independent value");
621	        // 各层节点数 5 -> 3 -> 2 -> 1：位置 4 连续两次原样提升，
622	        // 只在最后一层记录一个左侧兄弟。
623	        const std::size_t expected_siblings[5] = {3, 3, 3, 3, 1};
624	        for (std::uint64_t i = 0; i < 5; ++i) {
625	            const branchaudit::MerkleProofResult r =
626	                branchaudit::merkle_proof_file(batch, i);
627	            check(r.ok(), "proof 5-file index " + std::to_string(i) + ": ok");
628	            check(r.proof.leaf_count == 5 && r.proof.leaf_index == i,
629	                  "proof 5-file: count/index echoed");
630	            check(r.proof.root == root,
631	                  "proof 5-file: root equals merkle_root_files result");
632	            check(r.proof.siblings.size() == expected_siblings[i],
633	                  "proof 5-file index " + std::to_string(i) +
634	                      ": sibling count matches tree shape");
635	            check(fold_proof(r.proof) == r.proof.root,
636	                  "proof 5-file index " + std::to_string(i) +
637	                      ": siblings fold back to root");
638	        }
639	        // 位置 4 的唯一兄弟是左侧的 parent(parent(La,Labc), parent(Lempty,Lhello))。
640	        const branchaudit::MerkleProofResult r4 =
641	            branchaudit::merkle_proof_file(batch, 4);
642	        const Digest left_subtree = branchaudit::merkle_parent(
643	            branchaudit::merkle_parent(la, labc),
644	            branchaudit::merkle_parent(lempty, leaf_bytes(hello)));
645	        check(r4.proof.siblings.size() == 1 &&
646	                  r4.proof.siblings[0].side == branchaudit::MerkleSibling::Side::left &&
647	                  r4.proof.siblings[0].digest == left_subtree,
648	              "proof index 4: promoted twice, single left sibling at the top");
649	    }
650	
651	    // 重复路径与相同内容各占独立位置，证明按位置区分。
652	    {
653	        const std::vector<fs::path> batch{f_a, f_a};
654	        const branchaudit::MerkleProofResult r0 =
655	            branchaudit::merkle_proof_file(batch, 0);
656	        const branchaudit::MerkleProofResult r1 =
657	            branchaudit::merkle_proof_file(batch, 1);
658	        check(r0.ok() && r1.ok() && r0.proof.root == r1.proof.root &&
659	                  r0.proof.leaf == r1.proof.leaf &&
660	                  r0.proof.siblings[0].side == branchaudit::MerkleSibling::Side::right &&
661	                  r1.proof.siblings[0].side == branchaudit::MerkleSibling::Side::left,
662	              "proof repeated path: two positions, mirrored sibling sides");
663	        check(r0.proof.root == root_of(batch),
664	              "proof repeated path: root matches root command semantics");
665	    }
666	
667	    // 库接口失败：位置越界（含空批次）、文件失败；不打印、不退出。
668	    {
669	        branchaudit::MerkleProofResult r =
670	            branchaudit::merkle_proof_file({f_a}, 1);
671	        check(!r.ok(), "proof index out of range: fails");
672	        r = branchaudit::merkle_proof_file({}, 0);
673	        check(!r.ok(), "proof empty batch: no valid position");
674	        const fs::path missing = tmp.root / "missing 缺失.bin";
675	        std::stringstream cap_out, cap_err;
676	        auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
677	        auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
678	        r = branchaudit::merkle_proof_file({f_a, missing, f_abc}, 0);
679	        std::cout.rdbuf(old_out);
680	        std::cerr.rdbuf(old_err);
681	        check(!r.ok(), "proof with a failing file: whole operation fails");
682	        check(r.error.find(missing.string()) != std::string::npos,
683	              "proof file failure: error names the failed path");
684	        check(cap_out.str().empty() && cap_err.str().empty(),
685	              "proof library: prints nothing, does not exit");
686	    }
687	}
688	
689	// ---- 大文件：流式读取、尾部敏感 -------------------------------------------
690	
691	void test_large_files() {
692	    TempArea tmp("large");
693	    const std::vector<unsigned char> big = fill_a(200000);
694	    const std::vector<unsigned char> pat = pattern(200000);
695	    const fs::path f_big = tmp.root / "a200000.bin";
696	    const fs::path f_pat = tmp.root / "pattern200000.bin";
697	    write_file(f_big, big);
698	    write_file(f_pat, pat);
699	
700	    check(hex_of(root_of({f_big})) ==
701	              "0ce74c178a2d90235341a8a2e17539e34aad75dfead1f361b5bec500c1eff93e",
702	          "single large file leaf (streaming)");
703	    check(hex_of(root_of({f_big, f_pat})) ==
704	              "a801ef6c29a4ee3e4e2bc339c7437fe24a2bc10b86571825062a80f6a374daa0",
705	          "root [big, pattern]");
706	    check(hex_of(root_of({f_pat, f_big})) ==
707	              "892596758489f559ec8778ed1d271cd52b18a340926ef47cd16481a432bf2494",
708	          "root [pattern, big] differs under reversal");
709	
710	    // 仅最后一个字节不同：叶子必须随之改变（流式尾部不遗漏）。
711	    std::vector<unsigned char> tail = big;
712	    tail.back() = static_cast<unsigned char>('b');
713	    const fs::path f_tail = tmp.root / "a200000tail.bin";
714	    write_file(f_tail, tail);
715	    check(hex_of(root_of({f_tail})) ==
716	              "e705589769e167619ac6a979e5e06f245ff1ff34a65f34e261b728abc4698a75",
717	          "large file: changing last byte changes leaf/root");
718	    check(root_of({f_tail}) != root_of({f_big}),
719	          "large file: tail change is detected");
720	}
721	
722	}  // namespace
723	
724	int main(int argc, char** argv) {
725	    fault_test::ensure_fault_preloaded(argc, argv);
726	
727	    test_empty_batch();
728	    test_leaf_rule();
729	    test_parent_rule();
730	    test_file_batches();
731	    test_relative_paths();
732	    test_failures();
733	    if (fault_test::kFaultInjectionAvailable) {
734	        test_io_failures();
735	    } else {
736	        // 平台无 LD_PRELOAD//proc 故障注入支持（如 macOS）：明确报告
737	        // 跳过，不计入已通过检查。
738	        ++g_skipped;
739	        std::cout << "SKIP: unopenable-leaf and mid-read-error checks "
740	                     "(fault injection not supported on this platform)\n";
741	    }
742	    test_large_files();
743	    test_proofs();
744	
745	    if (g_failures == 0) {
746	        std::cout << "all " << g_checks << " merkle regression checks passed";
747	        if (g_skipped > 0) {
748	            std::cout << " (" << g_skipped << " platform-specific check group"
749	                         " skipped, not verified)";
750	        }
751	        std::cout << '\n';
752	        return 0;
753	    }
754	    std::cerr << g_failures << " of " << g_checks << " checks failed\n";
755	    return 1;
756	}
