// ---- 64 位计数边界：纯结构推导，不按 leaf_count 分配内存 --------------------

// 沿 (leaf_count, leaf_index) 计算生成端会记录的兄弟数与各层期望侧向，
// 用独立的一份循环模拟证明形状（不调用生成接口，也不需要真实文件）。
struct ShapeStep {
    MerkleSibling::Side side;
};
std::vector<ShapeStep> expected_shape(std::uint64_t leaf_count,
                                      std::uint64_t leaf_index) {
    std::vector<ShapeStep> steps;
    std::uint64_t n = leaf_count;
    std::uint64_t pos = leaf_index;
    while (n > 1) {
        const bool promoted = (pos % 2 == 0) && (pos == n - 1);
        if (!promoted) {
            steps.push_back({(pos % 2 == 0) ? MerkleSibling::Side::right
                                            : MerkleSibling::Side::left});
        }
        pos /= 2;
        n -= n / 2;
    }
    return steps;
}

void test_verify_uint64_limits() {
    // leaf_count = UINT64_MAX：最大可表示的合法计数。
    // 位置 0 每层都在偶数位；末层之前各层均为奇数（UINT64_MAX 是奇数，
    // 反复 ceil(n/2) 一直是奇数直到 1），位置 0 永远不是末节点，因此
    // 每层都有一个 right 兄弟，共 63 项（2^63 < 2^64-1，经 63 次提升后
    // 层大小为 2，再一层到 1）。
    constexpr std::uint64_t kMax = UINT64_MAX;
    {
        const std::vector<ShapeStep> shape = expected_shape(kMax, 0);
        check(shape.size() == 63,
              "UINT64_MAX leaves index 0: exactly 63 sibling levels");

        // 用期望形状构造一份“结构正确”的证明：叶子与兄弟摘要无意义，只
        // 要结构校验阶段不越界、不回绕、必定终止；随后折叠值不可能等于
        // 全零可信根，因此最终失败——但失败必须来自根比对，而不是崩溃、
        // 挂起或误判成结构通过。
        MerkleProof p;
        p.leaf_count = kMax;
        p.leaf_index = 0;
        Digest leaf{};
        leaf[31] = 0x7f;
        p.leaf = leaf;
        Digest node = leaf;
        for (const ShapeStep& st : shape) {
            Digest sib{};
            if (st.side == MerkleSibling::Side::right) {
                node = branchaudit::merkle_parent(node, sib);
                p.siblings.push_back({MerkleSibling::Side::right, sib});
            } else {
                node = branchaudit::merkle_parent(sib, node);
                p.siblings.push_back({MerkleSibling::Side::left, sib});
            }
        }
        p.root = node;

        const Digest trusted = node;  // 与折叠结果一致 -> 必须通过
        const MerkleVerifyResult ok =
            branchaudit::merkle_verify_proof(p, trusted, leaf);
        check(ok.ok(),
              "UINT64_MAX leaves: structurally exact proof verifies "
              "deterministically");

        // 可信根差一位：在完成全部 63 层结构核对后才失败于根比对。
        Digest other = trusted;
        other[0] ^= 0x80;
        const MerkleVerifyResult bad =
            branchaudit::merkle_verify_proof(p, other, leaf);
        check(!bad.ok(),
              "UINT64_MAX leaves: wrong trusted root is rejected after full "
              "structural traversal");

        // 少一个兄弟：结构校验在第 63 层前发现缺项，不能误判通过。
        MerkleProof short_proof = p;
        short_proof.siblings.pop_back();
        const MerkleVerifyResult missing =
            branchaudit::merkle_verify_proof(short_proof, trusted, leaf);
        check(!missing.ok(),
              "UINT64_MAX leaves: a missing sibling at the last level is "
              "detected");

        // 位置 UINT64_MAX-1（偶数，首节点……末节点的镜像）：首位置是奇数
        // 下标，必有 left 兄弟；形状仍为 63 项，推导必须无回绕。
        const std::vector<ShapeStep> shape_last =
            expected_shape(kMax, kMax - 1);
        check(shape_last.size() == 63 &&
                      shape_front_is_left(shape_last),
              "UINT64_MAX-1 index: 63 levels, first sibling on the left");
    }

    // 末位置 UINT64_MAX-1？再取真正的末位置 UINT64_MAX-1 已覆盖；另验
    // 偶数计数 UINT64_MAX-1（=2^64-2）下的末位置（偶数，是末节点，首层
    // 提升无兄弟），确认 == n-1 的判断在极限值上正确。
    {
        constexpr std::uint64_t kEven = UINT64_MAX - 1;  // 偶数
        const std::vector<ShapeStep> shape =
            expected_shape(kEven, kEven - 1);
        check(!shape.empty() &&
                      shape.front().side == MerkleSibling::Side::left,
              "even max-range count, last even index promotes without a "
              "first-level sibling");
        // 该证明首项缺失不会被判缺项：构造完整形状并通过校验。
        MerkleProof p;
        p.leaf_count = kEven;
        p.leaf_index = kEven - 1;
        Digest leaf{};
        leaf[0] = 0x33;
        p.leaf = leaf;
        Digest node = leaf;
        for (const ShapeStep& st : shape) {
            Digest sib{};
            if (st.side == MerkleSibling::Side::right) {
                node = branchaudit::merkle_parent(node, sib);
                p.siblings.push_back({MerkleSibling::Side::right, sib});
            } else {
                node = branchaudit::merkle_parent(sib, node);
                p.siblings.push_back({MerkleSibling::Side::left, sib});
            }
        }
        p.root = node;
        check(branchaudit::merkle_verify_proof(p, node, leaf).ok(),
              "max-range even count: promoted last index verifies without a "
              "padding record");
    }
}

